9		"os"
10		"path/filepath"
11	)
12	
13	// recordVersion 是当前记录文件格式版本。
14	const recordVersion = 1
15	
16	// fileData 是记录文件的磁盘格式。
17	type fileData struct {
18		Version       int            `json:"version"`
19		Courses       []*Course      `json:"courses"`
20		Students      []*Student     `json:"students"`
21		Requirements  []*Requirement `json:"requirements"`
22		Enrollments   []*Enrollment  `json:"enrollments"`
23		Waivers       []*Waiver      `json:"waivers"`
24		NextResultSeq int            `json:"nextResultSeq"`
25	}
26	
27	// Load 从 path 读取记录。
28	//
29	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
30	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
31	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
32	// 空文件同样视为损坏，而不是空记录。
33	//
34	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
35	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
36	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
37	// 绝不依据已读到的前半条记录继续办理业务。
38	//
39	// 同一个 JSON 对象内的字段归属只能确定一次：出现两个完全同名的字段，或
40	// 两个字段名只有大小写差异却都会被读取功能识别为同一条记录字段（课程的
41	// credit 与 Credit、修读的 student 与 Student、最外层的 courses 与
42	// COURSES 等），无论两个值是否相同、顺序是否相邻，整份文件都判为损坏。
43	// 规则同时适用于最外层对象与其中的每条课程、学生、要求、修读、免修记录：
44	// 后一份即使是空数组也不能盖掉前一份。字段名以 JSON 解码后的文字比较并
45	// 按现有解码规则做大小写折叠（直接写出、Unicode 转义、大小写写法语义
46	// 等同），无法用转义加大小写的组合绕开；限制只针对同一对象，不同记录
47	// 各自携带同名字段是正常结构，字符串值里提到字段名不算重复。只出现一次
48	// 的大小写写法仍照常识别（如只有 Credit 的课程按该值读取）；不指向任何
49	// 记录字段的未知键不在此列，继续按未知字段拒绝。
50	//
51	// JSON 字符串的原始内容必须能还原为合法 Unicode 文字：字符串中直接写入的
52	// 字节不是合法 UTF-8，或 \uXXXX 转义中出现未配对的高位/低位代理项（高位
53	// 代理项后没有紧跟低位代理项、孤立的低位代理项、两个高位代理项相连等），
54	// 整份文件都判为内容损坏——标准库会把这些内容静默替换成 U+FFFD，替换后的
55	// 编号或依据绝不能当成正常内容继续查询、核对或登记，哪怕问题只在一条已拒绝
56	// 免修的依据里或本次核对不涉及的课程名称里。检查只读不写：不替用户修补转义、
57	// 不删字符、不改动任何申请状态。合法文字不受影响：中文、直接写入的补充平面
58	// 字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实写入的
59	// “�”（U+FFFD）都按原样使用。
60	//
61	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
62	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
63	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
64	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
65	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
66	// 含实际文字的依据中原有空白。
67	func Load(path string) (s *Store, existed bool, err error) {
68		f, err := os.Open(path)
69		if err != nil {
70			if errors.Is(err, os.ErrNotExist) {
71				return NewStore(), false, nil
72			}
73			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
74		}
75		defer f.Close()
76	
77		fi, err := f.Stat()
78		if err != nil {
79			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
80		}
81		if fi.Size() == 0 {
82			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
83		}
84	
85		raw, err := io.ReadAll(f)
86		if err != nil {
87			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
88		}
89	
90		// 先按原始字节检查 JSON 字符串能否还原为合法 Unicode 文字。标准库解码
91		// 会把非法 UTF-8 字节与未配对的高/低位代理项转义静默替换成 U+FFFD，
92		// 替换后的学生编号、课程名称或免修依据绝不能当成正常内容继续办理业务
93		// （两个本来不同的编号可能被替换成同一个），这样的文件整份判为内容
94		// 损坏，哪怕问题只在一条已拒绝免修的依据里或本次核对不涉及的课程名称
95		// 里。检查只读不写：不修补转义、不删字符、不改动申请状态。
96		if err := scanStringUnicode(raw); err != nil {
97			return nil, true, fmt.Errorf(
98				"记录文件 %s 内容损坏（包含无效的 Unicode 文字：%v），未做任何修改",
99				path, err)
100		}
101	
102		// 先在 token 流上检查同一 JSON 对象内的字段归属。标准库直接解进结构
103		// 体时会用后一个重复键静默覆盖前一个，而且结构体字段按大小写不敏感
104		// 匹配 json 标签：同一门课程写了 "credit":4 与 "Credit":9（4 会被
105		// 9 悄悄顶替，两个键颠倒又变成 4），最外层同时写 courses 与 COURSES
106		// （后一份即使是空数组也会盖掉前一份），修读里的 student 与 Student
107		// 都无法明确说明字段归属。这样的记录必须整份判为损坏，绝不能据此
108		// 核对或办理——即使冲突只在本次查询没有涉及的课程或免修历史里。
109		// 仅扫描第一份完整值，其后内容仍由下方的“完整记录之后不得有多余
110		// 内容”检查处理。
111		var dupErr *duplicateFieldError
112		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
113			if dupErr.first == dupErr.second {
114				return nil, true, fmt.Errorf(
115					"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
116					path, dupErr.field)
117			}
118			return nil, true, fmt.Errorf(
119				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 与 %q 仅大小写不同，读取时都指向同一记录字段 %q，字段归属无法确定），未做任何修改",
120				path, dupErr.first, dupErr.second, dupErr.field)
121		}
122	
123		var data fileData
124		dec := json.NewDecoder(bytes.NewReader(raw))
125		dec.DisallowUnknownFields()
126		if err := dec.Decode(&data); err != nil {
127			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
128		}
129		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
130		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
131		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
132		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
133		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
134		// 片段。这些一律视为文件损坏。
135		var extra json.RawMessage
136		switch err := dec.Decode(&extra); {
137		case errors.Is(err, io.EOF):
138			// 唯一一份完整记录之后只有空白，符合格式。
139		case err == nil:
140			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
141		default:
142			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
143		}
144	
145		s = NewStore()
146		if err := s.loadData(&data); err != nil {
147			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
148		}
149		return s, true, nil
150	}
151	
152	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
153	func (s *Store) loadData(d *fileData) error {
154		if d.Version != recordVersion {
155			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
156		}
157	
158		// 课程
159		for _, c := range d.Courses {
160			if c == nil {
161				return errors.New("存在空的课程记录")
162			}
163			if c.ID == "" {
164				return errors.New("存在没有编号的课程")
165			}
166			if c.Name == "" {
167				return fmt.Errorf("课程 %s 没有名称", c.ID)
168			}
169			if c.Credit <= 0 {
170				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
171			}
172			if _, dup := s.courseByID[c.ID]; dup {
173				return fmt.Errorf("课程编号 %s 重复", c.ID)
174			}
175			s.courses = append(s.courses, c)
176			s.courseByID[c.ID] = c
177		}
178	
179		// 学生
180		for _, st := range d.Students {
181			if st == nil || st.ID == "" {
182				return errors.New("存在没有编号的学生记录")
183			}
184			if _, dup := s.studentByID[st.ID]; dup {
185				return fmt.Errorf("学生编号 %s 重复", st.ID)
186			}
187			s.students = append(s.students, st)
188			s.studentByID[st.ID] = st
189		}
190	
191		// 要求
192		for _, r := range d.Requirements {
193			if r == nil {
194				return errors.New("存在空的课程要求记录")
195			}
196			if r.StudentID == "" || r.ID == "" {
197				return errors.New("存在缺少学生编号或要求编号的课程要求")
198			}
199			if _, ok := s.studentByID[r.StudentID]; !ok {
200				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
201			}
202			if _, ok := s.courseByID[r.CourseID]; !ok {
203				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
204					r.StudentID, r.ID, r.CourseID)
205			}
206			key := reqKey(r.StudentID, r.ID)
207			if _, dup := s.reqByKey[key]; dup {
208				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
209			}
210			dk := dupKey(r.StudentID, r.CourseID)
211			if other, dup := s.reqByDup[dk]; dup {
212				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
213					r.StudentID, r.CourseID, other, r.ID)
214			}
215			s.requirements = append(s.requirements, r)
216			s.reqByKey[key] = r
217			s.reqByDup[dk] = r.ID
218		}
219	
220		// 修读
221		usedSeq := map[int]bool{}
222		for _, e := range d.Enrollments {
223			if e == nil {
224				return errors.New("存在空的修读记录")
225			}
226			if e.StudentID == "" || e.ID == "" {
227				return errors.New("存在缺少学生编号或修读编号的修读记录")
228			}
229			if _, ok := s.studentByID[e.StudentID]; !ok {
230				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
231			}
232			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
233			if r == nil {
234				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
235					e.StudentID, e.ID, e.ReqID)
236			}
237			if e.Term == "" {
238				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
239			}
240			switch e.Result {
241			case Enrolled, Passed, Failed:
242			default:
243				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
244			}
245			if e.Result == Enrolled {
246				if e.ResultSeq != 0 {
247					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
248				}
249			} else {
250				if e.ResultSeq <= 0 {
251					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
252				}
253				if usedSeq[e.ResultSeq] {
254					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
255				}
256				usedSeq[e.ResultSeq] = true
257			}
258			key := reqKey(e.StudentID, e.ID)
259			if _, dup := s.enrByKey[key]; dup {
260				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
261			}
262			s.enrollments = append(s.enrollments, e)
263			s.enrByKey[key] = e
264		}
265	
266		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
267		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
268		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
269		for _, w := range d.Waivers {
270			if w == nil {
271				return errors.New("存在空的免修记录")
272			}
273			if w.StudentID == "" || w.ID == "" {
274				return errors.New("存在缺少学生编号或免修编号的免修记录")
275			}
276			if _, ok := s.studentByID[w.StudentID]; !ok {
277				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
278			}
279			switch w.Status {
280			case WaiverApproved, WaiverRejected, WaiverRevoked:
281			default:
282				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
283			}
284			switch w.Status {
285			case WaiverApproved:
286				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
287				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
288				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
289				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
290				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
291				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
292				if blankBasis(w.Basis) {
293					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
294						w.StudentID, w.ID)
295				}
296				rk := reqKey(w.StudentID, w.ReqID)
297				if s.reqByKey[rk] == nil {
298					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
299				}
300				if other, dup := approvedReq[rk]; dup {
301					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
302						w.StudentID, w.ReqID, other, w.ID)
303				}
304				approvedReq[rk] = w.ID
305			case WaiverRevoked:
306				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
307				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
308				// 该免修所属学生名下（同号要求只在其他学生名下不算），
309				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
310				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
311				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
312				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
313				// 性限制。
314				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
315					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
316						w.StudentID, w.ID, w.ReqID)
317				}
318				if blankBasis(w.Basis) {
319					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
320				}
321			}
322			key := reqKey(w.StudentID, w.ID)
323			if _, dup := s.waiverByKey[key]; dup {
324				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
325			}
326			s.waivers = append(s.waivers, w)
327			s.waiverByKey[key] = w
328		}
329	
330		if d.NextResultSeq < 0 {
331			return errors.New("结果提交序号计数器为负数")
332		}
333		for seq := range usedSeq {
334			if seq > d.NextResultSeq {
335				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
336			}
337		}
338		s.nextResultSeq = d.NextResultSeq
339		return nil
340	}
341	
342	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
343	// 避免写到一半时损坏原文件。
344	func (s *Store) Save(path string) (err error) {
345		data := fileData{
346			Version:       recordVersion,
347			Courses:       s.courses,
348			Students:      s.students,
349			Requirements:  s.requirements,
350			Enrollments:   s.enrollments,
351			Waivers:       s.waivers,
352			NextResultSeq: s.nextResultSeq,
353		}
354		buf, err := json.MarshalIndent(&data, "", "  ")
355		if err != nil {
356			return fmt.Errorf("无法序列化记录：%w", err)
357		}
358		buf = append(buf, '\n')
359	
360		dir := filepath.Dir(path)
361		if dir == "" {
362			dir = "."
363		}
364		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
365		if err != nil {
366			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
367		}
368		tmpName := tmp.Name()
369		defer func() {
370			if err != nil {
371				tmp.Close()
372				os.Remove(tmpName)
373			}
374		}()
375		if _, err = tmp.Write(buf); err != nil {
376			return fmt.Errorf("写入记录文件失败：%w", err)
377		}
378		if err = tmp.Sync(); err != nil {
379			return fmt.Errorf("写入记录文件失败：%w", err)
380		}
381		if err = tmp.Close(); err != nil {
382			return fmt.Errorf("写入记录文件失败：%w", err)
383		}
384		if err = os.Chmod(tmpName, 0o600); err != nil {
385			return fmt.Errorf("设置记录文件权限失败：%w", err)
386		}
387		if err = os.Rename(tmpName, path); err != nil {
388			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
389		}
390		return nil
391	}
392

