1	package main
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	)
9	
10	// 本文件回归“保存阶段失败时的命令反馈”：业务结果在变更真正写入记录文件之前
11	// 不得出现在标准输出。每条断言都重新打开进程访问记录文件：
12	//   - 首次建立记录时父目录不存在：登记/更新/提交/撤销类命令必须退出码 2、
13	//     标准输出为空（不能先显示“已登记学生”），标准错误明确指出保存失败并
14	//     点名目标记录文件，不能出现“已从空记录开始并创建”，目标文件不得被创建；
15	//   - 修改已有记录时保存失败：同样退出码 2、标准输出为空，原文件逐字节保留，
16	//     本次新增内容不得落盘；
17	//   - 被业务拒绝但本应写入免修历史的首次申请，遇保存失败时不能显示“已记入
18	//     免修历史”，退出码 2（文件错误优先于业务拒绝码 1），历史中查不到该申请；
19	//   - 有效免修只有保存成功后才允许显示“有效”及获得学分的信息。
20	
21	// makeDirUnwritable 取消目录的写权限并在测试结束时恢复。以 root 运行时权限
22	// 位无法阻止写入，此时跳过相关用例。
23	func makeDirUnwritable(t *testing.T, dir string) {
24		t.Helper()
25		if os.Geteuid() == 0 {
26			t.Skip("root 账户不受目录写权限限制，无法模拟保存失败")
27		}
28		if err := os.Chmod(dir, 0o555); err != nil {
29			t.Fatalf("取消目录写权限失败：%v", err)
30		}
31		t.Cleanup(func() { _ = os.Chmod(dir, 0o755) })
32	}
33	
34	// assertSaveFailure 断言一次写入类命令在保存阶段失败：退出码 2、标准输出
35	// 没有任何业务内容，标准错误明确指出保存失败并点名目标记录文件。
36	func assertSaveFailure(t *testing.T, file string, args []string, forbidden []string, label string) {
37		t.Helper()
38		out, errText, code := runCLI(t, file, args...)
39		if code != exitFile {
40			t.Fatalf("%s：保存失败应退出码 %d，code=%d out=%q err=%q",
41				label, exitFile, code, out, errText)
42		}
43		if out != "" {
