6		"strings"
7		"testing"
8	)
9	
10	// 本文件回归“记录文件中的字符串必须能还原为合法 Unicode 文字”。
11	// 标准库 encoding/json 解码时会把非法 UTF-8 字节与未配对的高/低位代理项
12	// 转义静默替换成 U+FFFD（“�”），替换后的学生编号、课程名称或免修依据绝不
13	// 能被当成正常内容继续查询、核对或登记——遇到这样的字符串，整份记录文件
14	// 都必须判为内容损坏，哪怕问题只在一条已拒绝免修的依据里、或在与本次核对
15	// 无关的课程名称里。检查只读不写：不修补转义、不删字符、不改动申请状态，
16	// 原文件逐字节保留。合法文字（中文、直接写入的补充平面字符、完整的高低
17	// 代理项转义对、转义表达的控制字符、用户确实写入的“�”）仍按原规则使用。
18	
19	// uesc 拼出一个 JSON Unicode 转义序列：uesc("D800") 返回 6 个字符
20	// （反斜线、u、D、8、0、0）。用函数拼接是为了避免测试源码直接书写转义
21	// 文本时被编辑器或工具链转换。
22	func uesc(hex string) string { return string(rune(0x5C)) + "u" + hex }
23	
24	// unicodeBaseRecord 返回一份结构完整、引用齐全的记录 JSON：学生 s1 的
25	// 要求 r1 指向 4 学分课程 c1。各替换目标串唯一，便于用例把非法文字注入
26	// 学生编号、课程名称、免修依据或字段名。
27	func unicodeBaseRecord() string {
28		return `{
29	  "version": 1,
30	  "courses": [
31	    {"id": "c1", "name": "高等数学", "credit": 4, "open": true}
32	  ],
33	  "students": [
34	    {"id": "s1"}
35	  ],
36	  "requirements": [
37	    {"id": "r1", "student": "s1", "course": "c1"}
38	  ],
39	  "enrollments": [],
40	  "waivers": [],
41	  "nextResultSeq": 0
42	}
43	`
44	}
45	
46	// writeRawRecord 把原始 JSON 文本（可能含非法 UTF-8 字节）写入临时记录
47	// 文件，返回路径与原始字节。
48	func writeRawRecord(t *testing.T, content string) (path string, raw []byte) {
49		t.Helper()
50		path = filepath.Join(t.TempDir(), "records.json")
51		raw = []byte(content)
52		if err := os.WriteFile(path, raw, 0o600); err != nil {
53			t.Fatalf("写入测试记录失败：%v", err)
54		}
55		return path, raw
56	}
57	
58	// replaceOnce 把 base 中唯一出现的 old 替换为 rep。
59	func replaceOnce(t *testing.T, base, old, rep string) string {
60		t.Helper()
61		if strings.Count(base, old) != 1 {
62			t.Fatalf("基础记录中 %q 应恰好出现一次", old)
63		}
64		return strings.Replace(base, old, rep, 1)
65	}
66	
67	// assertInvalidUnicode 断言 Load 拒绝含无效 Unicode 文字的记录：报错点名
68	// 记录文件、说明内容损坏与无效的 Unicode 文字，文件标记为已存在（不能当作
69	// 空记录），且原文件逐字节保留。
70	func assertInvalidUnicode(t *testing.T, path string, raw []byte) {
71		t.Helper()
72		s, existed, err := Load(path)
73		if err == nil {
74			t.Fatalf("含无效 Unicode 文字的记录应判内容损坏拒绝读取，却得到 store=%v", s)
75		}
76		if !existed {
77			t.Fatalf("损坏文件应标记为已存在（不能当作空记录），existed=%v err=%v",
78				existed, err)
79		}
80		msg := err.Error()
81		for _, want := range []string{path, "内容损坏", "无效的 Unicode 文字"} {
82			if !strings.Contains(msg, want) {
83				t.Fatalf("错误信息应包含 %q，得到：%v", want, err)
84			}
85		}
86		got, readErr := os.ReadFile(path)
87		if readErr != nil {
88			t.Fatal(readErr)
89		}
90		if string(got) != string(raw) {
91			t.Fatalf("拒绝读取不得改写原文件\nwant=%q\n got=%q", raw, got)
92		}
93	}
94	
95	// TestLoadRejectsUnpairedSurrogateEscapes Unicode 转义中出现未配对的高/低位
96	// 代理项（高位后没有紧跟低位、孤立低位、两个高位相连等）时，无论出现在学生
97	// 编号、课程名称、已拒绝免修的依据还是字段名里，整份记录都判内容损坏。
98	func TestLoadRejectsUnpairedSurrogateEscapes(t *testing.T) {
99		hi, lo := uesc("D800"), uesc("DC00")
100		cases := map[string]struct{ old, rep string }{
101			"学生编号含孤立高位代理项":  {`"id": "s1"`, `"id": "s` + hi + `1"`},
102			"学生编号含孤立低位代理项":  {`"id": "s1"`, `"id": "s` + lo + `1"`},
103			"两个高位代理项相连":     {`"id": "s1"`, `"id": "s` + hi + hi + `1"`},
104			"高位代理项在字符串末尾":   {`"id": "s1"`, `"id": "s` + hi + `"`},
105			"高位代理项后直接写普通字符": {`"id": "s1"`, `"id": "s` + hi + `x"`},
106			"高位代理项后是普通字符转义": {`"id": "s1"`, `"id": "s` + hi + uesc("0041") + `"`},
107			"课程名称含孤立高位代理项":  {`"name": "高等数学"`, `"name": "` + hi + `数学"`},
108			"字段名含孤立低位代理项":   {`"students"`, `"stud` + lo + `ents"`},
109			"已拒绝免修的依据含孤立代理项": {`"waivers": []`,
110				`"waivers": [{"id": "w1", "student": "s1", "req": "r1", ` +
111					`"basis": "材料` + hi + `", "status": "rejected", ` +
112					`"reason": "免修依据为空"}]`},
113		}
114		for name, c := range cases {
115			t.Run(name, func(t *testing.T) {
116				content := replaceOnce(t, unicodeBaseRecord(), c.old, c.rep)
117				path, raw := writeRawRecord(t, content)
118				assertInvalidUnicode(t, path, raw)
119			})
120		}
121	}
122	
123	// TestLoadRejectsInvalidUTF8InStrings 字符串中直接写入的字节不是合法 UTF-8
124	// 时（孤立非法字节、截断序列、孤立延续字节、过长编码、用 UTF-8 直接编码的
125	// 代理项），无论出现在字段值还是字段名里，整份记录都判内容损坏。
126	func TestLoadRejectsInvalidUTF8InStrings(t *testing.T) {
127		bad := string([]byte{0xFF})              // 孤立非法字节
128		trunc := string([]byte{0xE9})            // 截断的多字节序列
129		cont := string([]byte{0x80})             // 孤立延续字节
130		overlong := string([]byte{0xC0, 0xAF})   // 过长编码
131		surr := string([]byte{0xED, 0xA0, 0x80}) // 用 UTF-8 直接编码的代理项
132		cases := map[string]struct{ old, rep string }{
133			"学生编号含孤立非法字节":        {`"id": "s1"`, `"id": "s` + bad + `1"`},
134			"课程名称含截断序列":          {`"name": "高等数学"`, `"name": "高` + trunc + `数学"`},
135			"学生编号含孤立延续字节":        {`"id": "s1"`, `"id": "s` + cont + `1"`},
136			"学生编号含过长编码":          {`"id": "s1"`, `"id": "s` + overlong + `1"`},
137			"学生编号含 UTF-8 编码的代理项": {`"id": "s1"`, `"id": "s` + surr + `1"`},
138			"字段名含非法字节":           {`"students"`, `"stud` + bad + `ents"`},
139			"已拒绝免修的依据含非法字节": {`"waivers": []`,
140				`"waivers": [{"id": "w1", "student": "s1", "req": "r1", ` +
141					`"basis": "材料` + bad + `", "status": "rejected", ` +
142					`"reason": "免修依据为空"}]`},
143		}
144		for name, c := range cases {
145			t.Run(name, func(t *testing.T) {
146				content := replaceOnce(t, unicodeBaseRecord(), c.old, c.rep)
147				path, raw := writeRawRecord(t, content)
148				assertInvalidUnicode(t, path, raw)
149			})
150		}
151	}
152	
153	// TestLoadRejectsInvalidUnicodeBeforeComparingIDs 两个编号分别含有不同的
154	// 未配对代理项转义，被标准库替换后会变成同一个“s�”：读取必须先判文件损坏，
155	// 绝不能拿替换后的文字去判断两个编号是否相同或重复。
156	func TestLoadRejectsInvalidUnicodeBeforeComparingIDs(t *testing.T) {
157		base := replaceOnce(t, unicodeBaseRecord(), `{"id": "s1"}`,
158			`{"id": "s`+uesc("D800")+`"}, {"id": "s`+uesc("DC00")+`"}`)
159		path, raw := writeRawRecord(t, base)
160	
161		s, existed, err := Load(path)
162		if err == nil {
163			t.Fatalf("含未配对代理项的记录应判内容损坏，却得到 store=%v", s)
164		}
165		if !existed {
166			t.Fatalf("应标记文件已存在，existed=%v err=%v", existed, err)
167		}
168		msg := err.Error()
169		if !strings.Contains(msg, "无效的 Unicode 文字") {
170			t.Fatalf("应报告无效的 Unicode 文字，得到：%v", err)
171		}
172		if strings.Contains(msg, "重复") {
173			t.Fatalf("不能用替换后的文字判断编号相同/重复，得到：%v", err)
174		}
175		got, readErr := os.ReadFile(path)
176		if readErr != nil {
177			t.Fatal(readErr)
178		}
179		if string(got) != string(raw) {
180			t.Fatal("拒绝读取不得改写原文件")
181		}
182	}
183	
184	// TestLoadAcceptsValidUnicodeText 合法文字仍按原规则正常使用：中文、直接写入
185	// 的补充平面字符、完整的高低代理项转义对、转义表达的控制字符，以及用户确实
186	// 写入的“�”（直接写出或转义写出）都不能让文件被判坏。
187	func TestLoadAcceptsValidUnicodeText(t *testing.T) {
188		cases := map[string]struct{ old, rep string }{
189			"直接写入的替换字符":   {`{"id": "s1"}`, `{"id": "s1"}, {"id": "s�1"}`},
190			"转义写出的替换字符":   {`{"id": "s1"}`, `{"id": "s1"}, {"id": "s` + uesc("FFFD") + `1"}`},
191			"完整代理项转义对":    {`"name": "高等数学"`, `"name": "` + uesc("D83D") + uesc("DE00") + `数学"`},
192			"直接写入的补充平面字符": {`"name": "高等数学"`, `"name": "😀数学"`},
193			"转义表达的控制字符":   {`{"id": "s1"}`, `{"id": "s1"}, {"id": "s` + uesc("0001") + `t"}`},
194			"转义表达的空白字符":   {`"name": "高等数学"`, `"name": "高等` + uesc("0020") + `数学"`},
195		}
196		for name, c := range cases {
197			t.Run(name, func(t *testing.T) {
198				content := replaceOnce(t, unicodeBaseRecord(), c.old, c.rep)
199				path, raw := writeRawRecord(t, content)
200				s, existed, err := Load(path)
201				if err != nil || !existed {
202					t.Fatalf("合法文字应正常读取，existed=%v err=%v", existed, err)
203				}
204				if s == nil {
205					t.Fatal("合法记录应返回可用 store")
206				}
207				got, readErr := os.ReadFile(path)
208				if readErr != nil {
209					t.Fatal(readErr)
210				}
211				if string(got) != string(raw) {
212					t.Fatal("只读访问不得改写原文件")
213				}
214			})
215		}
216	}
217	
218	// TestLoadValidUnicodeContentPreserved 合法文字解码后保持原意：完整代理项对
219	// 还原为对应的补充平面字符，用户写入的“�”按原样保留在编号里，可正常查询。
220	func TestLoadValidUnicodeContentPreserved(t *testing.T) {
221		base := unicodeBaseRecord()
222		base = replaceOnce(t, base, `"name": "高等数学"`,
223			`"name": "`+uesc("D83D")+uesc("DE00")+`数学"`)
224		base = replaceOnce(t, base, `{"id": "s1"}`, `{"id": "s1"}, {"id": "s�2"}`)
225		path, raw := writeRawRecord(t, base)
226	
227		s, existed, err := Load(path)
228		if err != nil || !existed {
229			t.Fatalf("合法记录应正常读取，existed=%v err=%v", existed, err)
230		}
231		if c := s.Course("c1"); c == nil || c.Name != "😀数学" {
232			t.Fatalf("完整代理项对应还原为原字符，得到 %+v", c)
233		}
234		if st := s.Student("s�2"); st == nil {
235			t.Fatal("用户确实写入的“�”是合法文字，学生应能按原编号查到")
236		}
237		rep := s.CheckStudent("s1")
238		if !rep.Found || rep.TotalCredits != 0 || len(rep.Unmet) != 1 {
239			t.Fatalf("合法记录应可正常核对，得到 %+v", rep)
240		}
241		got, readErr := os.ReadFile(path)
242		if readErr != nil {
243			t.Fatal(readErr)
244		}
245		if string(got) != string(raw) {
246			t.Fatal("只读访问不得改写原文件")
247		}
248	}
