283		}
284		_, errText, code := runCLI(t, file, "student", "s1")
285		if code != exitFile || !strings.Contains(errText, "内容损坏") {
286			t.Fatalf("损坏文件应报文件错误且退出码 %d，code=%d err=%q",
287				exitFile, code, errText)
288		}
289		got, err := os.ReadFile(file)
290		if err != nil {
291			t.Fatal(err)
292		}
293		if string(got) != "{ broken json" {
294			t.Fatal("损坏文件不应被覆盖")
295		}
296	}
