298	// TestCLITrailingContentRejectedForReadAndWrite 合法记录后面多出内容时，无论
299	// 本次是只读核对还是会写入的登记，都必须以文件错误退出码 2 结束：不产生任何
300	// 业务成功信息、不用已读到的前半份记录返回核对结果、也不把异常文件覆盖成
301	// 一份看似正常的新记录；原文件的每个字节都要保留。
302	func TestCLITrailingContentRejectedForReadAndWrite(t *testing.T) {
303		// 一份可正常核对的合法记录：s1 有一门 4 学分课程并已通过。
304		good := "{\n  \"version\": 1,\n  \"courses\": [\n" +
305			"    {\"id\": \"c1\", \"name\": \"数学\", \"credit\": 4, \"open\": true}\n  ],\n" +
306			"  \"students\": [\n    {\"id\": \"s1\"}\n  ],\n" +
307			"  \"requirements\": [\n" +
308			"    {\"student\": \"s1\", \"id\": \"r1\", \"course\": \"c1\"}\n  ],\n" +
309			"  \"enrollments\": [\n" +
310			"    {\"student\": \"s1\", \"req\": \"r1\", \"term\": \"2024春\", \"id\": \"e1\"," +
311			" \"result\": \"passed\", \"resultSeq\": 1}\n  ],\n" +
312			"  \"waivers\": null,\n  \"nextResultSeq\": 1\n}\n"
313	
314		tails := map[string]string{
315			"多余右花括号":     "}",
316			"多余右方括号":     "]",
317			"拼接第二份记录":    `{"version":1}`,
318			"尾部普通文字":     "未完待续",
319			"未写完的JSON片段": ` {"version":`,
320		}
321		for name, tail := range tails {
322			t.Run(name, func(t *testing.T) {
323				content := good + tail
324				file := filepath.Join(t.TempDir(), "records.json")
325				if err := os.WriteFile(file, []byte(content), 0o600); err != nil {
326					t.Fatal(err)
327				}
328	
329				// 只读核对：不能返回基于前半份记录的核对结果，不能显示总学分。
330				out, errText, code := runCLI(t, file, "check", "s1")
331				if code != exitFile {
332					t.Fatalf("%s：只读核对遇尾部内容应退出码 %d，code=%d out=%q err=%q",
333						name, exitFile, code, out, errText)
334				}
335				if out != "" {
336					t.Fatalf("%s：拒绝读取时不应有任何业务输出，out=%q", name, out)
337				}
338				if !strings.Contains(errText, "内容损坏") || !strings.Contains(errText, file) {
339					t.Fatalf("%s：错误输出应说明文件损坏并点名问题文件，err=%q", name, errText)
340				}
341	
342				// 登记学生（会触发写入）：不能报告登记成功，更不能覆盖异常原文件。
343				out, errText, code = runCLI(t, file, "student", "s9")
344				if code != exitFile {
345					t.Fatalf("%s：写入类操作遇尾部内容应退出码 %d，code=%d out=%q err=%q",
346						name, exitFile, code, out, errText)
347				}
348				if strings.Contains(out, "已登记学生") || strings.Contains(out, "成功") {
349					t.Fatalf("%s：不应出现业务成功信息，out=%q", name, out)
350				}
351				if !strings.Contains(errText, "内容损坏") {
352					t.Fatalf("%s：应向错误输出说明内容损坏，err=%q", name, errText)
353				}
354	
355				got, err := os.ReadFile(file)
356				if err != nil {
357					t.Fatal(err)
358				}
359				if string(got) != content {
360					t.Fatalf("%s：原文件内容（含尾部异常）必须原样保留\nwant=%q\n got=%q",
361						name, content, got)
362				}
363			})
364		}
365	}
