387	func TestCLIIdempotentCommandsDoNotGrow(t *testing.T) {
388		file := filepath.Join(t.TempDir(), "records.json")
389		runCLI(t, file, "student", "s1")
390		first, err := os.ReadFile(file)
391		if err != nil {
392			t.Fatal(err)
393		}
394		// 纯幂等重复操作后文件内容不变。
395		for _, args := range [][]string{
396			{"student", "s1"},
397			{"check", "s1"},
398			{"show", "s1"},
399		} {
400			if _, _, code := runCLI(t, file, args...); code != 0 {
401				t.Fatalf("命令 %v 失败", args)
402			}
403		}
404		// check/show 不产生变更；student 重复也不产生变更。
405		second, err := os.ReadFile(file)
406		if err != nil {
407			t.Fatal(err)
408		}
409		if string(first) != string(second) {
410			t.Fatalf("幂等命令不应改变记录文件\nfirst=%s\nsecond=%s", first, second)
411		}
412	}
