414	// setupCLISharedEnrollments 建立两名学生就同一门 4 学分课程的同号要求 r1 与
415	// 同一学期的同号修读 e1，并断言两份修读都成功登记、初始为选课、各自核对均为
416	// 0 学分且要求未满足。
417	func setupCLISharedEnrollments(t *testing.T, file string) {
418		t.Helper()
419		for _, st := range [][]string{
420			{"student", "s1"},
421			{"student", "s2"},
422			{"course", "c1", "高等数学", "4"},
423			{"req", "s1", "r1", "c1"},
424			{"req", "s2", "r1", "c1"},
425			{"enroll", "s1", "r1", "2024春", "e1"},
426			{"enroll", "s2", "r1", "2024春", "e1"},
427		} {
428			if _, errText, code := runCLI(t, file, st...); code != 0 {
429				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
430			}
431		}
432		for _, student := range []string{"s1", "s2"} {
433			out, _, code := runCLI(t, file, "show", student)
434			if code != 0 || !strings.Contains(out, "修读 e1：要求 r1，学期 2024春，结果：选课") {
435				t.Fatalf("学生 %s 的同号修读应已登记且初始为选课，code=%d out=%q",
436					student, code, out)
437			}
438			out, _, code = runCLI(t, file, "check", student)
439			if code != 0 || !strings.Contains(out, "总学分：0") ||
440				!strings.Contains(out, "未满足要求：[r1]") {
441				t.Fatalf("学生 %s 初始核对应为 0 学分且要求未满足，code=%d out=%q",
442					student, code, out)
443			}
444		}
445	}
