func runErrText(t *testing.T, file string, args ...string) string {
	t.Helper()
	_, errText, _ := runCLI(t, file, args...)
	return errText
}

// setupCLIForEnrollWaiver 建立 s1 -> r1 -> c1（4 学分）的基础记录。
func setupCLIForEnrollWaiver(t *testing.T, file string) {
